/* Chapter 2–6 original deeper reading and independent checks. Based on previously audited A1.1 chapter objectives; not publisher exercises. */
(()=>{'use strict';
const DATA={"edition":"Original Netzwerk A1.1","provenance":"Previously audited uploaded 166-page A1.1 Kurs- und Arbeitsbuch; chapter-level scope only; original instructional material pending teacher language QA","chapters":[{"number":2,"title":"Freunde, Kollegen und ich","coursebook":[17,26],"workbook":[88,99],"topics":[{"id":"c2-hobbies","title":"Talk about hobbies","goal":"Use an action with gern and ask about somebody else's interest.","explain":"A hobby becomes meaningful when you can do more than recognise its name. German often uses a verb followed by gern to say that you enjoy an activity: ich lese gern, ich schwimme gern or ich spiele gern Fußball. Begin with a complete sentence, then turn it into a question for another person. Notice that verbs change with the subject: ich spiele but du spielst. In an ordinary statement the conjugated verb normally takes second position. In a yes/no question it comes first. Build a two-person exchange instead of studying disconnected word lists.","examples":[["Ich spiele gern Tennis.","I enjoy playing tennis.","The action verb is followed by gern."],["Spielst du auch gern Tennis?","Do you also like playing tennis?","The yes/no question begins with spielst."],["Meine Freundin liest gern.","My friend likes reading.","The third-person verb takes the ending -t."]],"mistake":"Do not say Ich gern spiele Tennis. Keep spiele in second position in a statement.","check":{"question":"Choose the natural German sentence about enjoying music.","options":["Ich gern höre Musik.","Ich höre gern Musik.","Ich Musik hören gern."],"correct":1,"why":"Ich höre gern Musik uses the conjugated verb in second position and gern after it."}},{"id":"c2-calendar","title":"Days and meeting plans","goal":"Read a weekly plan and negotiate a meeting.","explain":"To arrange to meet, first find a day and then check availability. German weekdays are capitalised because they are nouns: Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag and Sonntag. Use am with a weekday, and combine it with expressions such as Zeit haben or sich treffen. A real conversation usually includes a question, a response and a possible alternative. Practise how to say that a day does not work without stopping the conversation. Look at a simple calendar, rather than memorising each day in isolation, and notice what happens when a time expression begins a sentence.","examples":[["Hast du am Donnerstag Zeit?","Do you have time on Thursday?","Am introduces the day."],["Am Freitag habe ich keine Zeit.","I have no time on Friday.","After the time phrase, habe still occupies the second position."],["Geht Samstag? Ja, gern.","Would Saturday work? Yes, gladly.","A simple way to agree on a new day."]],"mistake":"Am Donnerstag habe ich Zeit is correct; Am Donnerstag ich habe Zeit is not the usual statement order.","check":{"question":"Which invitation asks whether somebody has time on Tuesday?","options":["Hast du am Dienstag Zeit?","Haben ich Dienstag Zeit?","Wo ist die Dienstag?"],"correct":0,"why":"The correct yes/no question begins with Hast and uses am Dienstag."}},{"id":"c2-occupations","title":"Jobs and working hours","goal":"Recognise a simple occupational profile and describe work.","explain":"Short profiles commonly give a name, occupation, workplace and working hours. First find those facts before worrying about every unknown word. With sein, an occupation is usually named without ein or eine in a neutral job statement: Er ist Koch; Sie ist Ärztin. A workplace can then be expressed with arbeitet in. Work schedules use von … bis … followed by Uhr when necessary. Practising a complete profile helps you distinguish the occupation from the place where somebody works. It also reinforces pronouns and present-tense verb endings with er, sie, ich and wir.","examples":[["Lea ist Ärztin.","Lea is a doctor.","A profession after sein is normally stated without eine."],["Sie arbeitet im Krankenhaus.","She works in a hospital.","Arbeitet describes the workplace."],["Sie arbeitet von acht bis sechzehn Uhr.","She works from eight to sixteen o'clock.","Von ... bis ... states a time range."]],"mistake":"Do not use hat for the job in Sie hat Ärztin; use ist Ärztin.","check":{"question":"Which statement identifies a person's occupation?","options":["Er haben Lehrer.","Er ist Lehrer.","Er arbeitet Lehrer."],"correct":1,"why":"Er ist Lehrer uses sein to state the profession."}},{"id":"c2-articles","title":"Nouns, articles and plurals","goal":"Read nouns together with their articles and plural forms.","explain":"German nouns begin with capital letters and belong to grammatical genders. A noun should be learned together with der, die or das; the English meaning alone does not tell you the article. Plurals need separate attention because German uses several patterns: der Tag – die Tage, die Kollegin – die Kolleginnen, das Buch – die Bücher. The plural article is die, but that does not mean every singular noun takes die. Match article and noun on vocabulary cards, then add an example sentence and its plural. This helps you read professional profiles, hobbies and short texts accurately.","examples":[["der Tag – die Tage","the day – the days","A plural with -e."],["die Kollegin – die Kolleginnen","the female colleague – the female colleagues","A feminine noun with -nen in the plural."],["das Buch – die Bücher","the book – the books","The plural changes the vowel and adds -er."]],"mistake":"Do not assume a plural can always be made by adding -s.","check":{"question":"Which pair shows the correct plural of die Kollegin?","options":["die Kollegin – die Kollegins","die Kollegin – die Kolleginnen","die Kollegin – der Kollegin"],"correct":1,"why":"Kolleginnen is the ordinary plural; all plural nouns use die as the definite article."}},{"id":"c2-seasons","title":"Seasons, dates and short profiles","goal":"Connect leisure activities to the calendar.","explain":"A learner profile can include hobbies, days and seasons, but these are different kinds of time information. Use im with seasons: im Winter, im Frühling, im Sommer and im Herbst. Use am with weekdays, and practise numbers above twenty when you read ages, schedules and simple prices. To describe routines in a short profile, choose a person, an activity and a time phrase: Im Sommer fährt Jonas Rad. Starting with im Sommer puts the verb second; it does not change the person–verb agreement. Combine this with job information to write a believable three- or four-sentence introduction.","examples":[["Im Sommer fahre ich Rad.","I cycle in summer.","Im introduces a season."],["Am Montag arbeite ich.","I work on Monday.","Am introduces a weekday."],["Jonas ist Koch. Im Winter liest er gern.","Jonas is a cook. In winter he likes reading.","A short profile combines work and free time."]],"mistake":"Do not use am Sommer for a simple seasonal expression; use im Sommer.","check":{"question":"Which sentence refers to an activity in winter?","options":["Am Winter lese ich.","Im Winter lese ich gern.","Der Winter ich lese gern."],"correct":1,"why":"Im Winter is the expected phrase, with lese in second position."}}]},{"number":3,"title":"In der Stadt","coursebook":[27,36],"workbook":[100,111],"topics":[{"id":"c3-landmarks","title":"Places in the city","goal":"Identify public buildings and the nouns for them.","explain":"Start with an imagined city map and find a few recognisable places: der Bahnhof, das Rathaus, die Bank, das Museum and die Haltestelle. German nouns should be read with their articles because the article helps build later sentences. Ask Wo ist …? when you need the location of a known place. Ask Gibt es hier …? to find out whether a place exists nearby. Pictures and maps are useful only when their labels match the object being discussed. Say the full German phrase while pointing at the corresponding landmark rather than just naming a word from memory.","examples":[["Wo ist der Bahnhof?","Where is the station?","Wo asks for its location."],["Das ist das Rathaus.","That is the town hall.","The noun is paired with das."],["Gibt es hier eine Bank?","Is there a bank here?","The question asks whether the place exists."]],"mistake":"Do not learn Bahnhof without der, or Rathaus without das.","check":{"question":"What does das Rathaus identify?","options":["A museum","A town hall","A train station"],"correct":1,"why":"Rathaus is the town hall; Bahnhof is the railway station."}},{"id":"c3-articles","title":"Definite and indefinite articles","goal":"Introduce a place and refer to it again.","explain":"When a speaker introduces a new place, an indefinite article can be natural: Das ist ein Museum. After it is known, the speaker can refer to the same building with the definite article: Das Museum ist groß. Learn the pairs der/ein, die/eine and das/ein in simple nominative statements. These are not interchangeable endings. In a map conversation, one person can name an unfamiliar building and another can ask whether it is the same building they are looking for. Short contrastive examples help beginners see what articles do in context.","examples":[["Das ist ein Museum.","That is a museum.","An indefinite introduction."],["Das Museum ist groß.","The museum is big.","The same known museum."],["Das ist eine Schule. Die Schule ist alt.","That is a school. The school is old.","Feminine indefinite and definite forms."]],"mistake":"Do not use eine Museum; Museum takes das/ein in these examples.","check":{"question":"Which article completes Das ist ___ Museum?","options":["ein","eine","einen"],"correct":0,"why":"Museum is neuter and takes ein in this nominative phrase."}},{"id":"c3-negation","title":"Say that something is not there","goal":"Use kein to negate a noun phrase.","explain":"City conversations often involve something that cannot be found. One helpful pattern is Hier ist kein Bahnhof, meaning there is no station here. For feminine nouns, the form is keine: Hier ist keine Bank. Distinguish this from the general word nicht, which can negate other parts of a statement. Build the negative phrase around the noun rather than adding nein in front of an otherwise positive statement. It is useful to compare what a street has with what it does not have while looking at a small map. This gives the grammar a practical purpose.","examples":[["Hier ist ein Museum.","There is a museum here.","A positive noun phrase."],["Hier ist kein Museum.","There is no museum here.","The matching negative noun phrase."],["Hier ist keine Bank.","There is no bank here.","Feminine nouns use keine in this pattern."]],"mistake":"Nein Bahnhof is not a complete replacement for kein Bahnhof in a sentence.","check":{"question":"Choose the correct negative: Hier ist ___ Bank.","options":["keine","kein","keinen"],"correct":0,"why":"Die Bank is feminine, so the negative nominative article is keine."}},{"id":"c3-transport","title":"Use public transport words","goal":"Read a simple route notice and choose the right stop.","explain":"Transport vocabulary is easier when learned on a journey rather than as a list. Begin at der Bahnhof, find a bus or tram, then look for die Haltestelle. A passenger might ask Wo ist die Haltestelle? or Fährt der Bus zum Bahnhof? Practise recognising street names and stops before trying to give a route. A short notice can state a destination, a transport mode and a departure point. The task is to identify these three facts, not to translate every sign. Linking each phrase to a visual route helps students understand which direction or vehicle is appropriate.","examples":[["Wo ist die Haltestelle?","Where is the stop?","Asks for the stop's location."],["Ich fahre mit dem Bus.","I travel by bus.","A common useful phrase for transport."],["Der Bus fährt zum Bahnhof.","The bus goes to the station.","A route and destination."]],"mistake":"Do not confuse der Bahnhof (station) with die Haltestelle (stop).","check":{"question":"Which word identifies a bus or tram stop?","options":["das Rathaus","die Haltestelle","die Bäckerei"],"correct":1,"why":"Die Haltestelle is the stop; the other words name unrelated places."}},{"id":"c3-directions","title":"Give polite directions","goal":"Trace a route and give clear steps in order.","explain":"Directions must match the map. First locate a starting point and a destination; then trace the route with your finger. Combine geradeaus, links and rechts with a polite Sie command when speaking to a stranger: Gehen Sie bitte geradeaus. Biegen Sie dann rechts ab. Place the directions in order, because changing even one step may take the person elsewhere. Use Entschuldigung to ask politely and Danke at the end. Students should practise both understanding directions and producing them. A partner can check the instructions against the same simple map and identify the first step that goes wrong.","examples":[["Entschuldigung, wo ist das Museum?","Excuse me, where is the museum?","An appropriate opening request."],["Gehen Sie bitte geradeaus.","Please go straight ahead.","A polite instruction with Sie."],["Dann biegen Sie links ab.","Then turn left.","Dann signals the next step."]],"mistake":"Gehen Sie and Biegen Sie are polite commands; Gehst du is an ordinary question.","check":{"question":"Which polite direction means 'Turn right'?","options":["Biegen Sie rechts ab.","Gehen Sie links ab.","Rechts Sie biegen."],"correct":0,"why":"Biegen Sie rechts ab is a suitable polite imperative."}}]},{"number":4,"title":"Guten Appetit!","coursebook":[41,50],"workbook":[116,127],"topics":[{"id":"c4-meals","title":"Meals and food groups","goal":"Identify foods and talk about what you eat.","explain":"Learn food words through the situations in which they are needed. Frühstück, Mittagessen and Abendessen name meals; Brot, Käse, Obst and Gemüse name foods or food groups. German food nouns have articles that are worth learning with them: das Brot, der Käse, die Tomate. One useful starter exchange is Was isst du zum Frühstück? followed by a simple answer. Students should see real foods when possible and practise recognising them before composing long descriptions. Knowing whether a word is a meal, an ingredient or a place to shop prevents confusion in listening and reading tasks.","examples":[["Zum Frühstück esse ich Brot.","I eat bread for breakfast.","Names a meal and food."],["Der Käse ist frisch.","The cheese is fresh.","Käse takes der."],["Was isst du zum Mittagessen?","What do you eat for lunch?","A question about a meal."]],"mistake":"Do not treat die Bäckerei as a food; it is a shop.","check":{"question":"Which German word names the evening meal?","options":["das Frühstück","das Mittagessen","das Abendessen"],"correct":2,"why":"Das Abendessen is the evening meal."}},{"id":"c4-shops","title":"Where food is sold","goal":"Connect a product to the appropriate shop.","explain":"A shopping conversation becomes clearer when learners first identify where to buy something. Die Bäckerei is a bakery; die Metzgerei is a butcher's shop; der Markt may offer vegetables and other food. Ask whether the shop has the item before asking for a quantity. A short dialogue could begin Guten Tag. Haben Sie noch Brot? and continue Ja, natürlich. Students should distinguish a shop name from a food noun and listen for the central item in a request. Real shop photographs are helpful if they clearly show the product being discussed, rather than being only decorative.","examples":[["Ich gehe zur Bäckerei.","I am going to the bakery.","A place to buy bread."],["Haben Sie noch Brötchen?","Do you still have bread rolls?","Asks about availability."],["Ich kaufe Tomaten auf dem Markt.","I buy tomatoes at the market.","Connects an item to a place."]],"mistake":"Do not use die Metzgerei when the prompt is asking for the name of a bakery.","check":{"question":"Which shop is most suitable for bread rolls?","options":["die Bäckerei","die Apotheke","der Bahnhof"],"correct":0,"why":"Baked goods are commonly sold at a Bäckerei."}},{"id":"c4-quantities","title":"Quantities, lists and prices","goal":"Read a grocery list and ask how much something costs.","explain":"A useful shopping list contains quantities, not only item names. Compare zwei Tomaten, ein Stück Käse, eine Flasche Wasser and eine Packung Milch. These phrases help make the amount unambiguous. In a shop, you may ask Was kostet das? or Wie viel kostet das? and listen for the price. When several items are involved, ask Was kostet das zusammen? A reader should be able to find the needed quantity and total even if they do not understand every word on a receipt. Match the words to a drawn or photographed object and practise the full short request.","examples":[["Wir brauchen zwei Tomaten.","We need two tomatoes.","A countable quantity."],["Eine Packung Milch, bitte.","One carton of milk, please.","A packaging unit."],["Was kostet das zusammen?","How much is that altogether?","Requests a total."]],"mistake":"Eine Milch can be understood in some contexts, but eine Packung Milch is clearer for a carton on a list.","check":{"question":"Which phrase clearly requests a carton of milk?","options":["ein Milch","eine Packung Milch","einen Packung Milch"],"correct":1,"why":"Eine Packung Milch specifies the unit and matches Packung's feminine article."}},{"id":"c4-accusative","title":"Objects and the accusative","goal":"See why der becomes den in common purchase sentences.","explain":"In Das ist der Saft, the juice is the subject complement and the familiar nominative article is der. In Ich kaufe den Saft, the juice is the direct object of kaufe, and the masculine article changes to den. The parallel indefinite pair is ein → einen. In these simple examples, feminine die/eine and neuter das/ein do not change their form. Practice with full sentences instead of an isolated grammar table: Ich kaufe einen Apfel, eine Tomate und ein Brot. Ask what is being bought and identify the noun. Once the student understands the purpose, article choices become easier to remember.","examples":[["Der Apfel ist rot.","The apple is red.","Masculine nominative subject."],["Ich kaufe den Apfel.","I buy the apple.","Masculine accusative object."],["Ich kaufe einen Apfel und eine Tomate.","I buy an apple and a tomato.","Only the masculine indefinite article changes here."]],"mistake":"Ich kaufe ein Apfel is incorrect for an accusative masculine noun.","check":{"question":"Complete: Ich kaufe ___ Apfel.","options":["ein","eine","einen"],"correct":2,"why":"Apfel is masculine, so the direct object takes einen."}},{"id":"c4-shop-dialogue","title":"A complete shop exchange","goal":"Use greetings, requests, prices and thanks naturally.","explain":"To practise communication rather than isolated vocabulary, work through an entire short shopping situation. The customer greets the shopkeeper, asks for an item, checks the quantity or price, and ends politely. The shopkeeper may ask Sonst noch etwas?, meaning Anything else? Each line should have a clear purpose. A useful independent practice task gives the student a short list of food items and asks them to choose appropriate quantities. A partner acts as the seller and replies with prices. This is shop language for Chapter 4; a longer sit-down restaurant exchange is studied in Chapter 6.","examples":[["Guten Tag. Ich möchte zwei Brötchen.","Good day. I'd like two rolls.","A clear opening purchase request."],["Sonst noch etwas? Nein, danke.","Anything else? No, thanks.","Closes the ordering phase."],["Das macht drei Euro. Danke!","That's three euros. Thanks!","A short payment exchange."]],"mistake":"A shop exchange is not complete if it only gives a food word without a request.","check":{"question":"Which reply politely closes an offer of another item?","options":["Wo wohnst du?","Nein, danke.","Ich bin Arzt."],"correct":1,"why":"Nein, danke politely declines an additional item."}}]},{"number":5,"title":"Tag für Tag","coursebook":[51,60],"workbook":[128,139],"topics":[{"id":"c5-clocks","title":"Read analogue and digital time","goal":"Translate a time into everyday German language.","explain":"Time-telling is easiest when a student can see both the clock and the corresponding phrase. For 07:30, you may hear sieben Uhr dreißig or halb acht. The everyday phrase halb acht means half an hour before eight, not after it. Viertel nach acht is 08:15, while Viertel vor neun is 08:45. First practise recognising the hands or digits, then speak the German expression. When scheduling an event, add um to a precise time: Der Kurs beginnt um acht Uhr. Listening exercises should check whether the learner understood the hour, not just repeated a familiar sound.","examples":[["Es ist halb acht.","It is 7:30.","Halfway to eight."],["Es ist Viertel nach acht.","It is 8:15.","A quarter past eight."],["Der Kurs beginnt um neun Uhr.","The course starts at nine.","Um introduces a precise time."]],"mistake":"Halb neun is 08:30, not 09:30.","check":{"question":"Which time does halb neun indicate?","options":["08:30","09:30","09:15"],"correct":0,"why":"Halb neun means thirty minutes before nine."}},{"id":"c5-routine","title":"Describe a daily routine","goal":"Use time expressions with everyday actions and separable verbs.","explain":"A daily routine is a sequence, so start with the order of activities. Ich stehe um sieben Uhr auf, ich frühstücke um halb acht, and danach gehe ich zur Arbeit are linked statements about one day. Some common verbs are separable: aufstehen becomes ich stehe … auf in a simple statement. Notice that the verb stays in its usual position but its prefix appears at the end. If the time phrase begins the sentence, the finite verb remains second: Um sieben Uhr stehe ich auf. A short timetable helps students connect grammar with the order of their day.","examples":[["Ich stehe um sieben Uhr auf.","I get up at seven.","Auf stands at the end."],["Um halb acht frühstücke ich.","I have breakfast at 7:30.","The finite verb follows the initial time phrase."],["Danach gehe ich zur Arbeit.","Afterwards I go to work.","Danach orders the routine."]],"mistake":"Ich aufstehe um sieben Uhr is not the ordinary finite sentence pattern.","check":{"question":"Which sentence correctly uses aufstehen?","options":["Ich aufstehe um sieben Uhr.","Ich stehe um sieben Uhr auf.","Ich stehen auf sieben Uhr."],"correct":1,"why":"A separable verb places the prefix auf at the end."}},{"id":"c5-family","title":"Family and possessive words","goal":"Introduce family members with mein or meine.","explain":"When talking about family, learn both the relationship word and its grammatical gender: der Vater, die Mutter, das Kind. Possessive forms agree with the noun in these nominative patterns. Compare mein Vater, meine Mutter and mein Kind. This does not mean you change the form according to whether the speaker is male or female. Create a simple family profile with a name, relationship and one activity. A meaningful reading task might show a family photo with captions, asking which person is described. The captions should explicitly state the relationships rather than expecting students to guess them from appearance.","examples":[["Das ist mein Vater.","This is my father.","Vater is masculine."],["Das ist meine Mutter.","This is my mother.","Mutter is feminine."],["Mein Bruder arbeitet heute.","My brother is working today.","A possessive and a simple statement."]],"mistake":"Meine Vater is incorrect in this nominative phrase; use mein Vater.","check":{"question":"Which phrase is right for 'my mother'?","options":["mein Mutter","meine Mutter","meinen Mutter"],"correct":1,"why":"Mutter is feminine, so meine is used here."}},{"id":"c5-modal","title":"Modal verbs and sentence structure","goal":"Use können or müssen with a second verb.","explain":"Modal verbs express ability, possibility, necessity or desire. The modal changes with the person while the other verb remains an infinitive toward the end of the clause: Ich kann morgen kommen. Ich muss heute arbeiten. In a yes/no question, the modal comes first: Kannst du morgen kommen? The two-part structure is easier to understand if students highlight the conjugated modal and then the final action. Use real appointment or daily-routine examples rather than filling an arbitrary gap. Learners should be able to decline politely and explain why they cannot attend.","examples":[["Ich kann am Dienstag kommen.","I can come on Tuesday.","Können introduces the ability or possibility."],["Ich muss heute arbeiten.","I must work today.","Arbeiten is the final infinitive."],["Kannst du morgen kommen?","Can you come tomorrow?","The modal opens the yes/no question."]],"mistake":"Ich kann kommen morgen sounds unnatural for the intended simple sentence; keep kommen at the end.","check":{"question":"Complete: Ich ___ heute arbeiten.","options":["müssen","musst","muss"],"correct":2,"why":"Ich takes muss, followed by infinitive arbeiten."}},{"id":"c5-appointments","title":"Make, move and decline appointments","goal":"Combine a weekday and time in a polite message.","explain":"An appointment message should include a day, a time and a clear response. In German, am introduces a weekday and um introduces an exact hour: Haben Sie am Mittwoch um elf Uhr Zeit? A refusal can be polite and useful: Tut mir leid, am Mittwoch kann ich nicht. Then offer a realistic alternative instead of ending with no. A weekly calendar gives students enough information to check whether an appointment can actually be accepted. Practise reading a date and time from a note, proposing a new appointment, and confirming the final plan so both speakers agree on the same details.","examples":[["Haben Sie am Mittwoch Zeit?","Are you free on Wednesday?","Am introduces the weekday."],["Um elf Uhr habe ich Zeit.","I am free at eleven.","Um introduces the hour."],["Tut mir leid, am Donnerstag kann ich nicht.","Sorry, I can't on Thursday.","A polite decline using a modal."]],"mistake":"Do not mix up am for weekday and um for the clock time.","check":{"question":"Which question asks about an appointment at 11 on Wednesday?","options":["Haben Sie im Mittwoch elf Uhr Zeit?","Haben Sie am Mittwoch um elf Uhr Zeit?","Haben Sie um Mittwoch am elf Zeit?"],"correct":1,"why":"Use am Mittwoch and um elf Uhr."}}]},{"number":6,"title":"Zeit mit Freunden","coursebook":[61,70],"workbook":[140,151],"topics":[{"id":"c6-calendar","title":"Dates and invitations","goal":"Read a date correctly and give essential event details.","explain":"An invitation gives more than an activity name. A useful message states the occasion, date, time and place, then asks for a reply. German dates after am generally use an ordinal form: am dritten Mai, am vierzehnten Juni. When listening to an announcement, identify these pieces of information one at a time. A student can first highlight the date on a card, then write a short invitation and compare it with a sample. The writing task should be simple enough for an A1 beginner while still conveying where and when the guest should arrive.","examples":[["Ich habe am vierzehnten Juni Geburtstag.","My birthday is on 14 June.","The date uses an ordinal."],["Die Feier ist um vier Uhr.","The celebration is at four.","Um introduces the time."],["Kommst du am Samstag?","Are you coming on Saturday?","A direct invitation question."]],"mistake":"Am vierzehn Juni is not the full ordinal form used in this date phrase.","check":{"question":"Which phrase means 'on 3 May'?","options":["am drei Mai","am dritten Mai","um dritte Mai"],"correct":1,"why":"Am dritten Mai uses the ordinal with -ten in this example."}},{"id":"c6-plans","title":"Leisure plans and separable verbs","goal":"Use einladen and prepare a reply to an invitation.","explain":"A social plan can be accepted, declined or changed. The separable verb einladen illustrates how German verbs can split in ordinary present-tense statements: Ich lade dich ein. With a day added, Ich lade dich am Samstag ein. Similar everyday verbs can behave this way, so students should look at the whole sentence rather than searching only for a dictionary form. An invitation exchange is complete when the guest replies. Learn Ja, gern and Leider kann ich nicht before attempting a longer explanation. A practical activity lets students choose a real date from a calendar and propose an alternative when they are busy.","examples":[["Ich lade dich morgen ein.","I invite you tomorrow.","Lade and ein belong to einladen."],["Danke für die Einladung!","Thank you for the invitation!","A friendly reply."],["Leider kann ich nicht kommen.","Unfortunately I can't come.","A polite refusal with final infinitive."]],"mistake":"Ich einlade dich is incorrect in an ordinary finite statement.","check":{"question":"Choose the correctly separated statement.","options":["Ich einlade dich morgen.","Ich lade dich morgen ein.","Ich laden dich morgen ein."],"correct":1,"why":"The finite form is lade and the separated prefix is ein."}},{"id":"c6-restaurant","title":"A restaurant conversation","goal":"Order, check the total and ask for the bill.","explain":"A restaurant exchange follows a sequence: greeting, menu, ordering, a short response and payment. Practise identifying the stage of the exchange before focusing on grammatical endings. A useful customer phrase is Ich möchte eine Suppe, bitte. A waiter may ask Möchten Sie noch etwas? At the end, Die Rechnung, bitte is a common way to request the bill. A sample menu or receipt can connect words to prices, but the amounts must be internally consistent. Learners should rehearse a complete two-person exchange and verify that each line responds naturally to the previous one. This is different from the grocery-shop task in Chapter 4.","examples":[["Ich möchte eine Suppe, bitte.","I'd like a soup, please.","Polite ordering."],["Möchten Sie noch etwas?","Would you like anything else?","A server's follow-up question."],["Die Rechnung, bitte.","The bill, please.","Requests payment."]],"mistake":"Die Speisekarte (menu) and die Rechnung (bill) are not the same document.","check":{"question":"Which phrase asks for the bill?","options":["Die Rechnung, bitte.","Wo ist der Bahnhof?","Ich lese gern."],"correct":0,"why":"Die Rechnung, bitte requests the bill."}},{"id":"c6-pronouns","title":"Accusative object pronouns","goal":"Refer to a person already mentioned without repeating the name.","explain":"After learners recognise the direct object of a sentence, a short object pronoun can replace a name. In Ich sehe Anna, Anna is the object. The next sentence can be Ich sehe sie. For a masculine person, Ich sehe Paul becomes Ich sehe ihn. Compare nominative er/sie with accusative ihn/sie in complete examples so the role is clear. A reading activity can show two people discussing someone they know. Ask first whom the verb concerns, then choose the pronoun. Avoid teaching the forms as a detached table before students understand why the sentence needs an object.","examples":[["Ich sehe Anna. Ich sehe sie.","I see Anna. I see her.","Sie replaces a feminine object."],["Ich sehe Paul. Ich sehe ihn.","I see Paul. I see him.","Ihn replaces a masculine object."],["Sie kennt mich.","She knows me.","Mich is the object form of ich."]],"mistake":"Do not substitute er for ihn as a masculine direct object.","check":{"question":"Complete: Ich kenne Paul. Ich kenne ___.","options":["er","ihn","du"],"correct":1,"why":"Ihn is the masculine accusative pronoun in this sentence."}},{"id":"c6-past","title":"Talk about yesterday with war and hatte","goal":"Recognise frequent past forms of sein and haben.","explain":"For short accounts of yesterday, the forms war and hatte are especially useful. Compare Heute bin ich zu Hause with Gestern war ich zu Hause. Similarly, Heute habe ich Zeit becomes Gestern hatte ich Zeit. These past forms belong to sein and haben; they are not a pattern for forming the past of every German verb. Build three connected sentences around an ordinary evening: where someone was, whether they had time and whom they met or invited. The student should be able to identify whether the event is about now or yesterday from the verb and the time expression.","examples":[["Heute bin ich im Café.","Today I am at the café.","Present form bin."],["Gestern war ich im Café.","Yesterday I was at the café.","Past form war."],["Ich hatte gestern Zeit.","I had time yesterday.","Past form hatte."]],"mistake":"War is the past of sein, not a general past marker for every verb.","check":{"question":"Which means 'Yesterday I had time'?","options":["Gestern bin ich Zeit.","Gestern hatte ich Zeit.","Gestern habe ich Zeit morgen."],"correct":1,"why":"Hatte is the simple past form of haben."}}]}]};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chapter=n=>DATA.chapters.find(c=>c.number===Number(n));
const getTopic=id=>DATA.chapters.flatMap(c=>c.topics).find(t=>t.id===id);
function stats(n,progress){const c=chapter(n);if(!c)return {correct:0,answered:0,total:0};let answered=0,correct=0;for(const t of c.topics){const a=progress?.[t.id];if(a){answered++;if(a.correct)correct++;}}return {correct,answered,total:c.topics.length};}
function render(number,progress={},active='',expanded=false){
 const c=chapter(number);if(!c)return '';
 const counts=stats(number,progress);
 return `<section class="chapter-reader" aria-label="Extended chapter ${c.number} reading"><details class="chapter-reader-shell" data-reader-shell="${c.number}" ${expanded?'open':''}><summary class="chapter-reader-shell-toggle"><span class="reader-book-symbol" aria-hidden="true">▤</span><span><strong>Read the chapter in depth</strong><small>${c.topics.length} source-aligned explanations, worked examples and comprehension checks</small></span><span class="reader-progress">${counts.answered}/${counts.total} tried</span></summary><div class="reader-chapter-body"><p class="reader-intro">Follow the textbook topic sequence below. These are original explanations and exercises, not copied workbook pages. Open one part at a time.</p><div class="reader-topic-list">${c.topics.map((t,i)=>{const answer=progress?.[t.id];return `<details class="reader-topic" data-reader-topic="${esc(t.id)}" ${active===t.id?'open':''}><summary><span class="reader-topic-index">${c.number}.${i+1}</span><span><strong>${esc(t.title)}</strong><small>${esc(t.goal)}</small></span><span class="reader-topic-status">${answer?(answer.correct?'✓ Checked':'↺ Review'):'Open ↓'}</span></summary><div class="reader-topic-content"><p class="reader-explain">${esc(t.explain)}</p><h6>Work through the examples</h6><div class="reader-example-grid">${t.examples.map(([de,en,why])=>`<div class="reader-example"><strong lang="de">${esc(de)}</strong><span>${esc(en)}</span><p>${esc(why)}</p><button type="button" class="view-link" data-speak="${esc(de)}">♫ Listen</button></div>`).join('')}</div><p class="reader-mistake"><strong>Watch out:</strong> ${esc(t.mistake)}</p><div class="reader-selfcheck"><span class="eyebrow">Check your understanding</span><h6>${esc(t.check.question)}</h6><div class="reader-choices">${t.check.options.map((o,j)=>`<button type="button" data-reader-choice="${esc(t.id)}|${j}" ${answer?'disabled':''} class="${answer&&j===t.check.correct?'right':answer&&j===answer.chosen?'wrong':''}" aria-pressed="${answer?String(j===answer.chosen):'false'}">${esc(o)}</button>`).join('')}</div>${answer?`<p class="reader-feedback ${answer.correct?'right':'review'}"><strong>${answer.correct?'Correct.':'Review the pattern.'}</strong> ${esc(t.check.why)} <button type="button" class="view-link" data-reader-retry="${esc(t.id)}">Try again</button></p>`:''}</div></div></details>`;}).join('')}</div><p class="reader-source-note">Reference: original A1.1 Kursbuch PDF pages ${c.coursebook[0]}–${c.coursebook[1]}; corresponding Arbeitsbuch pages ${c.workbook[0]}–${c.workbook[1]}. No publisher text, artwork or audio reproduced.</p></div></details></section>`;
}
window.GERMAN_CHAPTER_READERS={data:DATA,chapter,getTopic,stats,render};
})();
